function close$VoucherBookTemplatesUpdateStatus$(f) {try {f.remove_onResponseComplete(on$Filter$VoucherBookTemplatesUpdateStatus$ResponseComplete);} catch (ex) {}}
function on$Filter$VoucherBookTemplatesUpdateStatus$ResponseComplete(sender, e) {
	var f = e.object, g = f.grid, context = e.type.Context, result = e.type.Result;
	switch (context) {
